// 1D presets of TENRYU Studio. Each one was run to its end time and checked against its physics
// (docs/beta/CHANGELOG.md, gui/manual §3). The meshes come from the 1D mesh skill
// (tenryu-mesh-1d): laser-driven presets carry the mesh that tools/assist recommend-mesh made and
// validated with a solver binary (presetMeshes.ts, regenerated by scripts/make_preset_meshes.sh);
// presets driven by a radiation temperature or a pressure, which the recommender does not cover,
// use a per-layer table built by the skill's rules (finest cells where the drive enters, widths
// continuous across material interfaces) and checked with a convergence pair.
import {
  defaultFormState,
  makeHotEChannel,
  type FormState,
  type MaterialForm,
  type RegionForm,
} from "./deck/formState";
import { defaultLayerZoning, type LayerZoningForm } from "./deck/mesh1d";
import { applyRecommendation, parseRecommendation } from "./deck/meshRecommend";
import { PRESET_MESHES, type PresetMeshId } from "./presetMeshes";
import { q } from "./units";

const um = (value: number) => q(value, "µm");

function idealMaterial(name: string, A: number, Z: number, kappaA = 0, cvEOverride?: number): MaterialForm {
  return {
    name,
    A,
    Z,
    eosModel: "ideal_gas",
    gamma: 5 / 3,
    cvEOverride,
    eosFile: "",
    opacityModel: "constant",
    kappaA,
    kappaS: 0,
    opacityFile: "",
  };
}

/** A material on a TMAT-H5 table of the repository (TMAT-H5/<file>, not in the beta distribution). */
function tableMaterial(name: string, A: number, Z: number, file: string, tableOpacity: boolean): MaterialForm {
  return {
    name,
    A,
    Z,
    eosModel: "tmat",
    gamma: 5 / 3,
    cvEOverride: undefined,
    eosFile: file,
    opacityModel: tableOpacity ? "tmat" : "constant",
    kappaA: 0,
    kappaS: 0,
    opacityFile: tableOpacity ? file : "",
  };
}

function region(materialName: string, rOuterUm: number, rho: number, temperatureEV: number): RegionForm {
  return {
    materialName,
    rOuter: um(rOuterUm),
    rho,
    Te: q(temperatureEV, "eV"),
    Ti: q(temperatureEV, "eV"),
  };
}

function layer(change: Partial<LayerZoningForm>): LayerZoningForm {
  return { ...defaultLayerZoning(), ...change };
}

/** Laser drive with the example suite's conventions: a ghost corona outside the bare surface,
 *  deposit smoothing, a single reference beam (f/3, centre focus) and the implicit conduction
 *  solver (SKILL tenryu-namelist §3; the mesh-convergence campaign behind recommend-mesh). */
function laserDrive(f: FormState, wavelengthNm: number, mode: FormState["laser"]["mode"]): void {
  f.laser.enabled = true;
  f.laser.wavelengthNm = wavelengthNm;
  f.laser.mode = mode;
  f.laser.raysPerBeam = 1000;
  f.laser.ghostCorona.enabled = true;
  f.laser.depositSmoothPasses = 3;
  f.laser.depositSmoothAlpha = 0.25;
  f.laser.beams[0] = { ...f.laser.beams[0], fNumber: 3.0, focusZUm: 0, w0Um: 250, superGaussianM: 4 };
  f.geometry.vacuumOutside1d = true;
  f.geometry.coronaRamp1d.enabled = false;
  f.conduction.enabled = true;
  f.conduction.solver = "implicit";
  f.conduction.fLim = 0.06;
}

/** Square pulse with linear rise and fall (W per cm² for planar targets, total W for spheres). */
function trapezoid(f: FormState, powerTW: number, flatNs: number, riseNs: number, fallNs: number): void {
  f.laser.waveformMode = "square";
  f.laser.powerW = q(powerTW, "TW");
  f.laser.pulseDuration = q(flatNs, "ns");
  f.laser.riseTime = q(riseNs, "ns");
  f.laser.fallTime = q(fallNs, "ns");
}

/** The recommended mesh stored for this preset (made for exactly these conditions). */
function recommendedMesh(f: FormState, id: PresetMeshId): void {
  const stored = PRESET_MESHES[id];
  if (stored === undefined) {
    // Not generated yet (scripts/make_preset_meshes.sh): a coarse placeholder.
    f.mesh.grid1d = "uniform";
    f.mesh.nr = 200;
    return;
  }
  applyRecommendation(f, parseRecommendation(JSON.stringify(stored.payload)), stored.conditionsKey, stored.binary, stored.createdAt);
}

function common(f: FormState, name: string, geometry: FormState["main"]["geometry1d"], tEndNs: number): void {
  f.main.name = name;
  f.main.dimension = "1D_SPH";
  f.main.geometry1d = geometry;
  f.main.tEnd = q(tEndNs, "ns");
  f.main.maxSteps = 10_000_000;
  f.mesh.rMin = q(0, "cm");
  f.radiation.enabled = false;
}

// ---------------------------------------------------------------------------------------------
// Basic

export function presetBlank(): FormState {
  return defaultFormState();
}

/** Planar CH foil on a rigid rear wall (the mid-plane of a foil twice as thick driven from both
 *  sides), 351 nm at 1e14 W/cm² for 1 ns; ideal-gas CH, no radiation. */
export function presetLaserFoil(): FormState {
  const f = defaultFormState();
  common(f, "laser_foil", "planar", 1.5);
  f.mesh.rMax = um(125);
  f.materials = [idealMaterial("CH", 6.5, 3.5)];
  f.geometry.regions = [region("CH", 25, 1.05, 0.025)];
  laserDrive(f, 351, "radial_absorption_1d");
  trapezoid(f, 100, 1.0, 0.1, 0.1);
  f.output.plotEveryS = q(20, "ps");
  recommendedMesh(f, "laserFoil");
  return f;
}

/** GXII-class direct-drive implosion: 7 µm CD shell (250 µm outer radius) on D2 gas, 527 nm
 *  Gaussian of 3e14 W/cm² peak (1 ns FWHM), ray tracing; ideal gas, no radiation. */
export function presetLaserShell(): FormState {
  const f = defaultFormState();
  common(f, "laser_shell_implosion", "spherical", 2.4);
  f.mesh.rMax = um(400);
  f.materials = [idealMaterial("D2", 2.01, 1.0), idealMaterial("CD", 7.0, 3.5)];
  f.geometry.regions = [region("D2", 243, 0.02, 0.025), region("CD", 250, 1.05, 0.025)];
  laserDrive(f, 527, "raytrace_2d");
  f.laser.waveformMode = "gaussian";
  f.laser.gaussianSpec = "peak";
  // 3e14 W/cm² over the target surface 4 pi (250 µm)^2.
  f.laser.gaussianPeakW = q((3.0e14 * 4 * Math.PI * 0.025 * 0.025) / 1.0e12, "TW");
  f.laser.gaussianFwhm = q(1.0, "ns");
  f.laser.gaussianCenter = q(1.2, "ns");
  f.output.plotEveryS = q(20, "ps");
  recommendedMesh(f, "laserShell");
  return f;
}

/** Marshak (radiation heat) wave into a static slab: gray FLD, 120 eV boundary, no hydro and no
 *  conduction; 1T with a fixed electron heat capacity. */
export function presetMarshakWave(): FormState {
  const f = defaultFormState();
  common(f, "marshak_wave", "planar", 1.0);
  f.main.temperatureModel = "1T";
  f.mesh.rMax = um(100);
  f.materials = [idealMaterial("CH", 6.5, 3.5, 2000.0, 3.0e11)];
  f.geometry.regions = [region("CH", 100, 0.2, 1.0)];
  f.geometry.radiationField = "zero";
  f.radiation.enabled = true;
  f.radiation.mode = "multigroup_diffusion";
  f.radiation.outerR = "marshak";
  f.radiation.marshakMode = "constant";
  f.radiation.marshakTrEV = 120.0;
  f.hydro.enabled = false;
  f.conduction.enabled = false;
  f.numerics.floors.TeFloorEV = 1.0;
  f.numerics.floors.TiFloorEV = 1.0;
  f.output.plotEveryS = q(20, "ps");
  // Finest cells (0.1 µm) where the radiation enters; 0.2 µm at the 1 ns front (~35 µm deep).
  f.mesh.grid1d = "layers";
  f.mesh.layerZoning = [layer({ cells: 300, spacing: "ratio", ratioSpec: "first_width", firstWidthCm: 0.1e-4, fineSide: "outer" })];
  return f;
}

/** Indirect-drive capsule: CH ablator on DT gas driven by a hohlraum radiation temperature Tr(t)
 *  (120 eV foot, 200 eV main) through the outer Marshak boundary; gray FLD, 2T. */
export function presetIndirectCapsule(): FormState {
  const f = defaultFormState();
  common(f, "indirect_drive_capsule", "spherical", 3.0);
  f.mesh.rMax = um(330);
  f.materials = [idealMaterial("DT", 2.5, 1.0, 1.0), idealMaterial("CH", 6.5, 3.5, 2000.0)];
  f.geometry.regions = [region("DT", 300, 0.01, 1e-3), region("CH", 330, 1.05, 1e-3)];
  f.geometry.radiationField = "zero";
  f.radiation.enabled = true;
  f.radiation.mode = "multigroup_diffusion";
  f.radiation.outerR = "marshak";
  f.radiation.marshakMode = "table";
  // The drive ends just after stagnation (2.4 ns). Held longer, the outermost cells of the blow-off
  // (at the density floor) keep accelerating under the outer Marshak boundary without bound
  // (5e9 cm/s at 2.45 ns, above 1e15 cm/s by 5 ns in the 2026-10-01 verification runs).
  f.radiation.marshakPoints = [
    { t: 0, v: 120 },
    { t: 0.5, v: 120 },
    { t: 1.0, v: 200 },
    { t: 2.4, v: 200 },
    { t: 2.6, v: 1 },
    { t: 3.0, v: 1 },
  ];
  f.conduction.enabled = true;
  f.conduction.solver = "implicit";
  f.numerics.dtInitial = q(1e-15, "s");
  f.numerics.floors.TeFloorEV = 1e-3;
  f.numerics.floors.TiFloorEV = 1e-3;
  f.output.plotEveryS = q(50, "ps");
  // Ablator: finest cells at both faces (ablation front outside, hot-spot boundary inside);
  // gas: the same width at the interface, coarsening toward the centre.
  f.mesh.grid1d = "layers";
  f.mesh.layerZoning = [
    layer({ cells: 150, spacing: "ratio", ratioSpec: "first_width", firstWidthCm: 0.05e-4, fineSide: "outer" }),
    layer({ cells: 120, spacing: "ratio", ratioSpec: "first_width", firstWidthCm: 0.05e-4, fineSide: "both" }),
  ];
  return f;
}

// ---------------------------------------------------------------------------------------------
// Optional kernels

/** Radiation-driven planar foil with discrete-ordinates (S_N, 16 directions) transport in four
 *  gray groups: a 150 eV drive through the outer boundary; 2T hydro with implicit conduction. */
export function presetSnRadiationFoil(): FormState {
  const f = defaultFormState();
  common(f, "sn_radiation_foil", "planar", 2.0);
  f.mesh.rMax = um(40);
  f.materials = [idealMaterial("CH", 6.5, 3.5, 2000.0)];
  f.geometry.regions = [region("CH", 40, 1.05, 0.025)];
  f.geometry.radiationField = "zero";
  f.radiation.enabled = true;
  f.radiation.mode = "sn_transport";
  f.radiation.snNAngles = 16;
  f.radiation.groups = 4;
  f.radiation.groupBoundsEV = [1, 100, 300, 1000, 10000];
  f.radiation.outerR = "marshak";
  f.radiation.marshakMode = "table";
  f.radiation.marshakPoints = [
    { t: 0, v: 10 },
    { t: 0.1, v: 150 },
    { t: 2.0, v: 150 },
  ];
  f.conduction.enabled = true;
  f.conduction.solver = "implicit";
  f.numerics.floors.TeFloorEV = 1e-3;
  f.numerics.floors.TiFloorEV = 1e-3;
  f.output.plotEveryS = q(20, "ps");
  f.mesh.grid1d = "layers";
  f.mesh.layerZoning = [layer({ cells: 200, spacing: "ratio", ratioSpec: "first_width", firstWidthCm: 0.05e-4, fineSide: "outer" })];
  return f;
}

/** Planar CH foil at 5e14 W/cm² (351 nm) with nonlocal electron transport (SNB). */
export function presetSnbFoil(): FormState {
  const f = defaultFormState();
  common(f, "snb_nonlocal_foil", "planar", 1.2);
  f.mesh.rMax = um(125);
  f.materials = [idealMaterial("CH", 6.5, 3.5)];
  f.geometry.regions = [region("CH", 25, 1.05, 0.025)];
  laserDrive(f, 351, "radial_absorption_1d");
  trapezoid(f, 500, 1.0, 0.1, 0.1);
  // The SNB correction runs on the explicit super-time-stepping solve (the solver refuses it with
  // the implicit one).
  f.conduction.nonlocalModel = "snb";
  f.conduction.solver = "sts";
  f.conduction.fLim = 0.5;
  f.output.plotEveryS = q(20, "ps");
  recommendedMesh(f, "snbFoil");
  return f;
}

/** Direct-drive shell with cross-beam energy transfer among the 12 GXII ports and hot electrons
 *  from two-plasmon decay and stimulated Raman scattering (threshold model), 351 nm at 5e14 W/cm²
 *  for 1 ns. CBET traces every ray on the slower path and costs a fixed amount per step on top of
 *  ray tracing, so the preset uses 200 rays per beam and stops after the pulse (1.2 ns). */
export function presetCbetHotElectrons(): FormState {
  const f = defaultFormState();
  common(f, "cbet_hot_electrons", "spherical", 1.2);
  f.mesh.rMax = um(400);
  f.materials = [idealMaterial("D2", 2.01, 1.0), idealMaterial("CD", 7.0, 3.5)];
  f.geometry.regions = [region("D2", 230, 0.0025, 0.025), region("CD", 250, 1.05, 0.025)];
  laserDrive(f, 351, "raytrace_2d");
  f.laser.raysPerBeam = 200;
  // 5e14 W/cm² over 4 pi (250 µm)^2.
  trapezoid(f, (5.0e14 * 4 * Math.PI * 0.025 * 0.025) / 1.0e12, 1.0, 0.1, 0.1);
  f.laser.cbet.enabled = true;
  f.laser.cbet.portPreset = "gxii";
  f.laser.hotE.enabled = true;
  f.laser.hotE.useChannels = true;
  f.laser.hotE.etaEvolution = "model";
  f.laser.hotE.subtractFromLaser = true;
  f.laser.hotE.channels = [makeHotEChannel("tpd"), makeHotEChannel("srs")];
  f.output.plotEveryS = q(20, "ps");
  recommendedMesh(f, "cbetHotElectrons");
  return f;
}

/** Radiation-driven DT exploding pusher with fusion burn (Fraley), ion plasma viscosity
 *  (Braginskii) and ion heat conduction: a 10 µm CD shell on 0.004 g/cc DT driven by a stepped
 *  Tr(t); eight gray groups. */
export function presetBurnPusher(): FormState {
  const f = defaultFormState();
  common(f, "burn_exploding_pusher", "spherical", 4.0);
  f.mesh.rMax = um(360);
  f.materials = [idealMaterial("DT", 2.5, 1.0, 1.0), idealMaterial("CD", 7.0, 3.5, 5000.0)];
  f.geometry.regions = [region("DT", 350, 0.004, 0.025), region("CD", 360, 1.05, 0.025)];
  f.geometry.radiationField = "zero";
  f.radiation.enabled = true;
  f.radiation.mode = "multigroup_diffusion";
  f.radiation.groups = 8;
  f.radiation.groupBoundsEV = [1, 3, 10, 30, 100, 300, 1000, 3000, 10000];
  f.radiation.outerR = "marshak";
  f.radiation.marshakMode = "table";
  f.radiation.marshakPoints = [
    { t: 0, v: 1 },
    { t: 0.2, v: 60 },
    { t: 0.8, v: 60 },
    { t: 1.0, v: 120 },
    { t: 1.8, v: 120 },
    { t: 2.2, v: 180 },
    { t: 3.2, v: 180 },
    { t: 3.5, v: 1 },
    { t: 4.0, v: 1 },
  ];
  f.conduction.enabled = true;
  f.conduction.solver = "implicit";
  f.conduction.ionConduction = true;
  f.hydro.plasmaVisc.enabled = true;
  f.hydro.plasmaVisc.model = "braginskii";
  f.hydro.plasmaVisc.species = "ion";
  f.burn.enabled = true;
  f.burn.fuels = { DT: true, DD: false, D3He: false };
  f.burn.scheme = "fraley";
  f.burn.partition = "fraley";
  f.burn.fuelMaterials = "DT";
  f.burn.xD = 0.5;
  f.burn.xT = 0.5;
  f.burn.xHe3 = 0;
  f.numerics.floors.TeFloorEV = 1e-3;
  f.numerics.floors.TiFloorEV = 1e-3;
  f.output.plotEveryS = q(50, "ps");
  f.mesh.grid1d = "layers";
  f.mesh.layerZoning = [
    layer({ cells: 150, spacing: "ratio", ratioSpec: "first_width", firstWidthCm: 0.1e-4, fineSide: "outer" }),
    layer({ cells: 60, spacing: "ratio", ratioSpec: "first_width", firstWidthCm: 0.05e-4, fineSide: "both" }),
  ];
  return f;
}

