/** Planar CD foil on the CD table (EOS and 80-group opacity) with multigroup flux-limited
 *  diffusion, 351 nm at 1e14 W/cm²; needs TMAT-H5/CD.tmat.h5 on the server. */
export function presetTableRadiationFoil(): FormState {
  const f = defaultFormState();
  common(f, "table_radiation_foil", "planar", 1.5);
  f.mesh.rMax = um(125);
  f.materials = [tableMaterial("CD", 7.0, 3.5, "TMAT-H5/CD.tmat.h5", true)];
  f.geometry.regions = [region("CD", 25, 1.05, 1.0)];
  f.geometry.radiationField = "zero";
  f.radiation.enabled = true;
  f.radiation.mode = "multigroup_diffusion";
  f.radiation.groups = 80;
  f.radiation.groupBoundsEV = [...TABLE_GROUP_BOUNDS_EV];
  f.radiation.outerR = "vacuum";
  laserDrive(f, 351, "radial_absorption_1d");
  trapezoid(f, 100, 1.0, 0.1, 0.1);
  f.numerics.floors.TeFloorEV = 0.1;
  f.numerics.floors.TiFloorEV = 0.1;
  f.output.plotEveryS = q(20, "ps");
  recommendedMesh(f, "tableRadiationFoil");
  return f;
}

/** Planar CD ablator on liquid D2 on the TMAT tables, both held in mechanical equilibrium at their
 *  initial state by the cold-equilibrium constitutive branch until heated (no motion before the
 *  shock arrives); 351 nm at 1e14 W/cm². Needs TMAT-H5/CD.tmat.h5 and TMAT-H5/D2.tmat.h5. */
export function presetColdEquilibriumLayers(): FormState {
  const f = defaultFormState();
  common(f, "cold_equilibrium_layers", "planar", 1.5);
  f.mesh.rMax = um(175);
  f.materials = [
    tableMaterial("D2", 2.01, 1.0, "TMAT-H5/D2.tmat.h5", false),
    tableMaterial("CD", 7.0, 3.5, "TMAT-H5/CD.tmat.h5", false),
  ];
  f.geometry.regions = [region("D2", 50, 0.17, 0.1), region("CD", 75, 1.05, 0.1)];
  laserDrive(f, 351, "radial_absorption_1d");
  trapezoid(f, 100, 1.0, 0.1, 0.1);
  f.hydro.inactiveCells = "cold_equilibrium";
  f.hydro.tStartEV = 2.0;
  f.hydro.qeiHeatCapacity = "table";
  // Reference states: the initial density and temperature, zero pressure, and the measured bulk
  // moduli of liquid D2 (1.2e9 dyn/cm², Richardson et al. 2014) and polystyrene (5.8e10 dyn/cm²,
  // Topp & Cahill 1996), the values the cold-equilibrium design records.
  f.materials[0].coldReference = { rhoGcc: 0.17, Te0: q(0.1, "eV"), Ti0: q(0.1, "eV"), P0: q(0, "GPa"), K0: q(0.12, "GPa") };
  f.materials[1].coldReference = { rhoGcc: 1.05, Te0: q(0.1, "eV"), Ti0: q(0.1, "eV"), P0: q(0, "GPa"), K0: q(5.8, "GPa") };
  f.numerics.floors.TeFloorEV = 0.1;
  f.numerics.floors.TiFloorEV = 0.1;
  f.output.plotEveryS = q(20, "ps");
  recommendedMesh(f, "coldEquilibriumLayers");
  return f;
}

/** Shock driven by a constant 1 Mbar pressure on the outer face of an ideal-gas slab (hydro
 *  only, 1T): the shock speed and the post-shock state have the exact Rankine-Hugoniot values. */
export function presetPressureShock(): FormState {
  const f = defaultFormState();
  common(f, "pressure_driven_shock", "planar", 5.0);
  f.main.temperatureModel = "1T";
  f.mesh.rMax = um(100);
  f.materials = [idealMaterial("CH", 6.5, 3.5)];
  f.geometry.regions = [region("CH", 100, 1.05, 1e-3)];
  f.hydro.enabled = true;
  f.hydro.boundary1d = "pressure";
  f.hydro.boundaryPressure = { mode: "constant", value: q(1, "Mbar"), points: [{ t: 0, v: 1 }, { t: 5, v: 1 }] };
  f.conduction.enabled = false;
  f.numerics.floors.TeFloorEV = 1e-3;
  f.numerics.floors.TiFloorEV = 1e-3;
  f.output.plotEveryS = q(100, "ps");
  f.mesh.grid1d = "layers";
  f.mesh.layerZoning = [layer({ cells: 400, spacing: "width" })];
  return f;
}

export interface Preset1d {
  id: string;
  build: () => FormState;
  category: "basic" | "option";
  /** TMAT-H5 tables the preset needs on the server (not in the beta distribution). */
  tables: string[];
  /** The run takes hours on one GPU (the card says so). */
  heavy?: boolean;
}

